from pathlib import Path

SOURCE = Path('src/decision_kernel/runtime/current_state_delivery.py')
TEST = Path('tests/test_current_state_research_work_read.py')


def replace_once(text: str, old: str, new: str) -> str:
    assert text.count(old) == 1, (old[:100], text.count(old))
    return text.replace(old, new, 1)


def replace_between(text: str, start: str, end: str, new: str) -> str:
    i = text.index(start)
    j = text.index(end, i)
    return text[:i] + new + text[j:]


text = SOURCE.read_text()
text = replace_once(text, 'RESEARCH_WORK_API_RESERVE = 12\n', 'RESEARCH_WORK_METADATA_CALLS = 2\n')
text = replace_once(
    text,
    '        self.inbox_job_gaps = []\n\n    def retain(self, path: str, raw: bytes) -> dict:\n',
    '''        self.inbox_job_gaps = []\n\n    def _publication_calls(self, file_count: int) -> int:\n        model.check(type(file_count) is int and file_count >= 0, "publication file count invalid")\n        # publish(): one blob write per file, then tree + commit + immutable\n        # current-state readback + ref write, plus previous-tree lookup when present.\n        return file_count + 4 + int(self.previous_commit is not None)\n\n    def retain(self, path: str, raw: bytes) -> dict:\n''')

text = replace_once(
    text,
    '''        model.check(type(config["max_items"]) is int and 1 <= config["max_items"] <= MAX_RESEARCH_WORK_ITEMS,\n                    "research work read item bound invalid")\n\n        ref = self.api.get("git/ref/heads/" + work.WORK_REF)["object"]\n''',
    '''        model.check(type(config["max_items"]) is int and 1 <= config["max_items"] <= MAX_RESEARCH_WORK_ITEMS,\n                    "research work read item bound invalid")\n\n        used = getattr(self.api, "calls", None)\n        if type(used) is int:\n            model.check(used + RESEARCH_WORK_METADATA_CALLS\n                        + self._publication_calls(len(self.files) + 2) <= MAX_API_CALLS,\n                        "research work metadata would consume base publication budget")\n\n        ref = self.api.get("git/ref/heads/" + work.WORK_REF)["object"]\n''')

old_budget_start = '        extra_reads = len(keys)  # work_inventory reads every reserved packet exactly once.\n'
old_budget_end = '        _, work_files = work_inventory(self.api, work_commit)\n'
new_budget = '''        source_paths: set[str] = set()\n        for key, names in keys.items():\n            packet_path = work.request_path(key)\n            source_paths.add(packet_path)\n            has_candidate = "candidate.json" in names or "input.json" in names\n            has_failure = "failure.json" in names\n            model.check(not (has_candidate and has_failure),\n                        "research work item contains both candidate and pre-execution failure")\n            if has_candidate:\n                model.check({"input.json", "candidate.json"}.issubset(names),\n                            "research work candidate lacks input or candidate")\n                base = prefix + key + "/"\n                source_paths.update({base + "input.json", base + "candidate.json"})\n                if "funnel.json" in names:\n                    source_paths.add(base + "funnel.json")\n            if has_failure:\n                source_paths.add(prefix + key + "/failure.json")\n\n        for path in source_paths:\n            row = rows[path]\n            model.check(row.get("mode") == "100644" and type(row.get("size")) is int\n                        and 0 <= row["size"] <= model.MAX_ARCHIVE,\n                        "research work source metadata invalid")\n        new_source_count = sum((path, work_commit) not in self.sources for path in source_paths)\n        model.check(len(self.sources) + new_source_count <= MAX_SOURCE_FILES,\n                    "research work read would exceed source-file budget")\n        projected_source_bytes = sum(rows[path]["size"] for path in source_paths\n                                     if (path, work_commit) not in self.sources)\n        model.check(sum(len(value) for value in self.files.values()) + projected_source_bytes\n                    <= MAX_RETAINED_OUTPUT,\n                    "research work read would exceed retained-output budget")\n        # Conservatively count one remote body read per selected source. work_inventory's\n        # recursive-tree GET is memoized from the metadata read above.\n        body_reads = len(source_paths)\n        used = getattr(self.api, "calls", None)\n        if type(used) is int:\n            projected_files = len(self.files) + new_source_count + 2\n            model.check(used + body_reads + self._publication_calls(projected_files) <= MAX_API_CALLS,\n                        "research work bodies would consume publication budget")\n\n        _, work_files = work_inventory(self.api, work_commit)\n'''
text = replace_between(text, old_budget_start, old_budget_end, new_budget)

old_retained_start = '        def retained(path: str, raw: bytes) -> dict:\n'
old_retained_end = '        items = []\n'
new_retained = '''        def retained(path: str, raw: bytes) -> dict:\n            source_key = (path, work_commit)\n            if source_key in self.sources:\n                prior_raw, reference = self.sources[source_key]\n                model.check(prior_raw == raw, "cached research work source bytes differ")\n                return reference\n            model.check(len(self.sources) < MAX_SOURCE_FILES, "source registry bound")\n            row = rows[path]\n            model.check(row.get("mode") == "100644" and row.get("size") == len(raw)\n                        and row.get("sha") == model.blob_sha(raw), "research work blob differs")\n            stored = self.retain("sources/git/" + row["sha"] + "/" + Path(path).name, raw)\n            reference = {"repository": model.REPOSITORY, "ref": work_commit, "path": path,\n                         "git_blob": row["sha"], **stored}\n            self.sources[source_key] = (raw, reference)\n            return reference\n\n        def fetched(path: str) -> tuple[bytes, dict]:\n            source_key = (path, work_commit)\n            if source_key in self.sources:\n                return self.sources[source_key]\n            raw = self.api.file(path, work_commit)\n            return raw, retained(path, raw)\n\n        items = []\n'''
text = replace_between(text, old_retained_start, old_retained_end, new_retained)

old_optional_start = '        work_config = registry.get("research_work_read")\n'
old_optional_end = '        return {"production_configuration": configuration, "production_inputs": packages,\n'
new_optional = '''        handoffs = project_registered_handoffs(entries, self.source)\n        work_config = registry.get("research_work_read")\n        if work_config is None:\n            candidate_work = {"status": "NOT_CONFIGURED",\n                              "meaning": "NO_AUTODISCOVERED_RESEARCH_WORK_READ_REQUESTED"}\n        else:\n            files_before = dict(self.files)\n            sources_before = dict(self.sources)\n            try:\n                candidate_work = self.research_work(work_config)\n            except (ValueError, KeyError, TypeError, AttributeError, IndexError, OSError, RuntimeError) as exc:\n                # Optional projection is transactional in memory. API reads cannot be\n                # undone, so preflight budgeting above guarantees base publication\n                # remains affordable even after a failed optional attempt.\n                self.files = files_before\n                self.sources = sources_before\n                candidate_work = {"status": "UNAVAILABLE_OR_REJECTED", "error_type": type(exc).__name__,\n                                  "meaning": "RESEARCH_WORK_NOT_QUIET_AND_NOT_PROMOTED"}\n                gaps.append({"status": "RESEARCH_WORK_READ_UNAVAILABLE_NOT_QUIET",\n                             "error_type": type(exc).__name__})\n        return {"production_configuration": configuration, "production_inputs": packages,\n'''
text = replace_between(text, old_optional_start, old_optional_end, new_optional)
text = replace_once(text, '                "handoffs": project_registered_handoffs(entries, self.source), "gaps": gaps,\n',
                    '                "handoffs": handoffs, "gaps": gaps,\n')

collect_start = '    def collect(self, refresh: dict) -> dict:\n'
collect_end = '\n\ndef publish(api, files: dict[str, bytes], previous_commit: str | None, code_commit: str, reading_hash: str) -> str:\n'
new_collect = '''    def collect(self, refresh: dict) -> dict:\n        started = self.now()\n        raw, registry_ref = self.source({"path": REGISTRY_PATH})\n        registry = json.loads(raw)\n        model.check(registry["schema_version"] == 1, "registry unsupported")\n        lanes = {name: self.lane(name) for name in model.WORKFLOWS}\n        # Capabilities are mandatory baseline reads, so complete them before the\n        # optional retained-Research projection can spend any of the shared budget.\n        capabilities = []\n        for item in registry["capability_gaps"]:\n            try:\n                _, reference = self.source(item["source"])\n                capabilities.append({"id": item["id"], "status": item["status"], "source": reference})\n            except (ValueError, KeyError, TypeError, AttributeError, IndexError, OSError, RuntimeError):\n                capabilities.append({"id": item["id"], "status": "ACCEPTANCE_SOURCE_UNAVAILABLE"})\n        research = self.research(registry)\n        research["registry"] = registry_ref\n        payload = model.assemble(code_commit=self.code_commit, checked_at=self.now(), check_started_at=started,\n                                 lanes=lanes, research=research, capabilities=capabilities, refresh_identity=refresh)\n        current_raw = model.json_bytes(payload)\n        summary_raw = model.render_summary(payload).encode()\n        model.check(sum(len(value) for value in self.files.values()) + len(current_raw) + len(summary_raw)\n                    <= MAX_RETAINED_OUTPUT, "reading retention batch limit")\n        used = getattr(self.api, "calls", None)\n        if type(used) is int:\n            model.check(used + self._publication_calls(len(self.files) + 2) <= MAX_API_CALLS,\n                        "collection leaves insufficient publication API budget")\n        self.retain("current-state.json", current_raw)\n        self.retain("README.md", summary_raw)\n        return payload\n'''
text = replace_between(text, collect_start, collect_end, new_collect)
SOURCE.write_text(text)


test = TEST.read_text()
old_api_test = '''def test_api_reserve_stops_before_packet_reads(tmp_path):\n    key, files = candidate_files()\n    c, api = collector(tmp_path, files, starting_calls=delivery.MAX_API_CALLS - delivery.RESEARCH_WORK_API_RESERVE - 2)\n    with pytest.raises(ValueError, match="API reserve"):\n        c.research_work(CONFIG)\n    assert not any(row.startswith("file:") for row in api.reads)\n    assert work.request_path(key) in files\n\n\n'''
new_api_test = '''def test_optional_metadata_cannot_consume_exact_base_publication_budget(tmp_path):\n    _, files = candidate_files()\n    c, api = collector(tmp_path, files, starting_calls=72)\n    c.previous_commit = "c" * 40\n    c.files = {f"already/{i}.json": b"x" for i in range(100)}\n    before = dict(c.files)\n    with pytest.raises(ValueError, match="base publication budget"):\n        c.research_work(CONFIG)\n    assert c.files == before and api.reads == []\n\n\n'''
test = replace_once(test, old_api_test, new_api_test)

old_invalid = '''def test_invalid_candidate_is_a_visible_research_gap_not_fallback(tmp_path, monkeypatch):\n    _, files = candidate_files()\n    candidate_path = next(p for p in files if p.endswith("candidate.json"))\n    damaged = json.loads(files[candidate_path])\n    damaged["input_hash"] = "0" * 64\n    files[candidate_path] = read.json_bytes(damaged)\n    c, _ = collector(tmp_path, files)\n    monkeypatch.setattr(c, "source", lambda spec: (\n        b"decision_packages=(\\n)\\nresearch_attention_handoffs=(\\n)\\n",\n        {"path": spec["path"], "ref": CODE},\n    ))\n    result = c.research({"references": [], "historical_handoffs": [],\n                         "additional_registered_handoffs": [], "research_work_read": CONFIG})\n    assert result["candidate_work"]["status"] == "UNAVAILABLE_OR_REJECTED"\n    assert any(gap["status"] == "RESEARCH_WORK_READ_UNAVAILABLE_NOT_QUIET" for gap in result["gaps"])\n    assert not result["handoffs"]["active"]\n\n\n'''
new_invalid = '''def test_invalid_candidate_is_a_visible_research_gap_not_fallback(tmp_path, monkeypatch):\n    _, files = candidate_files()\n    candidate_path = next(p for p in files if p.endswith("candidate.json"))\n    damaged = json.loads(files[candidate_path])\n    damaged["input_hash"] = "0" * 64\n    files[candidate_path] = read.json_bytes(damaged)\n    c, _ = collector(tmp_path, files)\n    c.files = {"baseline.txt": b"keep"}\n    c.sources = {("baseline.txt", CODE): (b"keep", {"read_path": "baseline.txt"})}\n    files_before, sources_before = dict(c.files), dict(c.sources)\n    monkeypatch.setattr(c, "source", lambda spec: (\n        b"decision_packages=(\\n)\\nresearch_attention_handoffs=(\\n)\\n",\n        {"path": spec["path"], "ref": CODE},\n    ))\n    result = c.research({"references": [], "historical_handoffs": [],\n                         "additional_registered_handoffs": [], "research_work_read": CONFIG})\n    assert result["candidate_work"]["status"] == "UNAVAILABLE_OR_REJECTED"\n    assert any(gap["status"] == "RESEARCH_WORK_READ_UNAVAILABLE_NOT_QUIET" for gap in result["gaps"])\n    assert not result["handoffs"]["active"]\n    assert c.files == files_before and c.sources == sources_before\n\n\n'''
test = replace_once(test, old_invalid, new_invalid)

marker = '@pytest.mark.parametrize("change", [\n'
addition = '''def test_successful_work_sources_populate_existing_source_cache(tmp_path):\n    key, files = candidate_files()\n    c, _ = collector(tmp_path, files)\n    value = c.research_work(CONFIG)\n    assert value["status"] == "READ_OK"\n    base = work.WORK_PREFIX + key + "/"\n    for name in ("packet.json", "input.json", "candidate.json", "funnel.json"):\n        assert (base + name, WORK) in c.sources\n\n\ndef test_retention_overflow_rejects_optional_work_without_leaking_projection(tmp_path, monkeypatch):\n    _, files = candidate_files()\n    c, api = collector(tmp_path, files)\n    c.files = {"baseline.txt": b"keep"}\n    before = dict(c.files)\n    monkeypatch.setattr(delivery, "MAX_RETAINED_OUTPUT", len(b"keep"))\n    monkeypatch.setattr(c, "source", lambda spec: (\n        b"decision_packages=(\\n)\\nresearch_attention_handoffs=(\\n)\\n",\n        {"path": spec["path"], "ref": CODE},\n    ))\n    result = c.research({"references": [], "historical_handoffs": [],\n                         "additional_registered_handoffs": [], "research_work_read": CONFIG})\n    assert result["candidate_work"]["status"] == "UNAVAILABLE_OR_REJECTED"\n    assert c.files == before and c.sources == {}\n    assert not any(row.startswith("file:") for row in api.reads)\n\n\ndef test_capabilities_and_registered_handoffs_finish_before_optional_work(tmp_path, monkeypatch):\n    c, _ = collector(tmp_path, {})\n    order = []\n    registry = {"schema_version": 1, "references": [], "historical_handoffs": [],\n                "additional_registered_handoffs": [], "research_work_read": CONFIG,\n                "capability_gaps": [{"id": "cap", "status": "KNOWN", "source": {"path": "cap.txt"}}]}\n    workflow = b"decision_packages=(\\n)\\nresearch_attention_handoffs=(\\n)\\n"\n    def source(spec):\n        path = spec["path"]\n        if path == delivery.REGISTRY_PATH:\n            return read.json_bytes(registry), {"path": path, "ref": CODE}\n        if path == read.WORKFLOWS["inbox"]:\n            return workflow, {"path": path, "ref": CODE}\n        if path == "cap.txt":\n            order.append("capability")\n            return b"cap", {"path": path, "ref": CODE}\n        raise AssertionError(path)\n    monkeypatch.setattr(c, "source", source)\n    monkeypatch.setattr(c, "lane", lambda name: {"name": name})\n    def handoffs(entries, loader):\n        order.append("handoffs")\n        return {"active": [], "background": [], "resolved_history": [], "gaps": []}\n    monkeypatch.setattr(delivery, "project_registered_handoffs", handoffs)\n    def optional(config):\n        assert order == ["capability", "handoffs"]\n        order.append("optional")\n        return {"status": "READ_OK", "items": []}\n    monkeypatch.setattr(c, "research_work", optional)\n    monkeypatch.setattr(delivery.model, "assemble", lambda **kwargs: {"reading_hash": "a" * 64})\n    monkeypatch.setattr(delivery.model, "render_summary", lambda payload: "ok")\n    c.collect({})\n    assert order == ["capability", "handoffs", "optional"]\n\n\n'''
assert test.count(marker) == 1 and 'test_successful_work_sources_populate_existing_source_cache' not in test
test = test.replace(marker, addition + marker, 1)
TEST.write_text(test)
